+export function createMemoryLeaderboard(initial: LeaderboardEntry[] = []): LeaderboardClient {
+  let entries = [...initial];
+  let nextId = Math.max(0, ...entries.map((entry) => entry.id)) + 1;
+
+  const ordered = () =>
